ModelInputPayload.source:
class ModelInputPayload:
    target_history: tuple[
        tuple[float, ...],
        ...,
    ]

    neighbor_histories: tuple[
        tuple[
            tuple[float, ...],
            ...,
        ],
        ...,
    ]

    neighbor_mask: tuple[
        float,
        ...,
    ]

    map_context: tuple[
        float,
        ...,
    ]

    def __post_init__(self) -> None:
        if len(
            self.target_history
        ) != HISTORY_STEPS:
            raise ValueError(
                "Target history length "
                "must be 11."
            )

        if any(
            len(row)
            !=
            FEATURE_DIM
            for row in self.target_history
        ):
            raise ValueError(
                "Target feature width changed."
            )

        if len(
            self.neighbor_histories
        ) != MAX_NEIGHBORS:
            raise ValueError(
                "Neighbor slot count changed."
            )

        for history in (
            self.neighbor_histories
        ):
            if len(history) != (
                HISTORY_STEPS
            ):
                raise ValueError(
                    "Neighbor history length "
                    "changed."
                )

            if any(
                len(row)
                !=
                FEATURE_DIM
                for row in history
            ):
                raise ValueError(
                    "Neighbor feature width "
                    "changed."
                )

        if len(
            self.neighbor_mask
        ) != MAX_NEIGHBORS:
            raise ValueError(
                "Neighbor mask length changed."
            )

        if len(
            self.map_context
        ) != MAP_CONTEXT_DIM:
            raise ValueError(
                "Map-context width changed."
            )

        if not all(
            isfinite(float(x))
            for x in self.map_context
        ):
            raise ValueError(
                "Map context must be finite."
            )

    def numeric_dict(
        self,
    ) -> dict:
        """
        Only numeric model input.

        No prediction IDs.
        No WOMD track IDs.
        No actor class.
        No truth track index.
        No future labels.
        """

        return {
            "target_history":
                self.target_history,

            "neighbor_histories":
                self.neighbor_histories,

            "neighbor_mask":
                self.neighbor_mask,

            "map_context":
                self.map_context,
        }

    def sha256(
        self,
    ) -> str:
        encoded = json.dumps(
            self.numeric_dict(),
            sort_keys=True,
            separators=(
                ",",
                ":",
            ),
            allow_nan=False,
        ).encode("utf-8")

        return sha256(
            encoded
        ).hexdigest()

