def build_causal_scene_inputs(
    associated_tracks,
    *,
    scenario_id: str,
    context,
    timestamps_s: tuple[
        float,
        ...,
    ],
) -> CausalSceneInputs:
    histories = []

    for associated_track in (
        associated_tracks
    ):
        try:
            history = (
                build_causal_track_history(
                    associated_track,
                    context=context,
                    timestamps_s=(
                        timestamps_s
                    ),
                )
            )

        except ValueError:
            continue

        histories.append(
            history
        )

    histories.sort(
        key=lambda history:
            history.prediction_id
    )

    return CausalSceneInputs(
        scenario_id=scenario_id,
        timestamps_s=(
            timestamps_s
        ),
        histories=tuple(
            histories
        ),
    )

