def build_model_input_payload(
    scene_inputs: CausalSceneInputs,
    *,
    prediction_id: str,
    map_context: tuple[
        float,
        ...,
    ],
) -> ModelInputPayload:
    target = (
        scene_inputs
        .history_by_id(
            prediction_id
        )
    )

    tx, ty, _ = (
        target
        .latest_position_H0_m
    )

    candidates = []

    for history in (
        scene_inputs.histories
    ):
        if (
            history.prediction_id
            ==
            prediction_id
        ):
            continue

        x, y, _ = (
            history
            .latest_position_H0_m
        )

        distance = hypot(
            x - tx,
            y - ty,
        )

        candidates.append(
            (
                distance,
                history.prediction_id,
                history,
            )
        )

    candidates.sort(
        key=lambda item: (
            item[0],
            item[1],
        )
    )

    selected = [
        item[2]
        for item in candidates[
            :MAX_NEIGHBORS
        ]
    ]

    neighbor_histories = [
        history.feature_rows()
        for history in selected
    ]

    neighbor_mask = [
        1.0
        for _ in selected
    ]

    while len(
        neighbor_histories
    ) < MAX_NEIGHBORS:
        neighbor_histories.append(
            zero_history_rows()
        )

        neighbor_mask.append(
            0.0
        )

    return ModelInputPayload(
        target_history=(
            target.feature_rows()
        ),
        neighbor_histories=tuple(
            neighbor_histories
        ),
        neighbor_mask=tuple(
            neighbor_mask
        ),
        map_context=tuple(
            float(x)
            for x in map_context
        ),
    )

