def build_real_causal_inputs(
    scenario,
    *,
    clean_config,
    degraded_config,
):
    adapted = (
        adapt_causal_womd_scenario(
            scenario
        )
    )

    ideal = (
        build_real_ideal_observation_scene(
            raw_scenario=scenario,
            adapted=adapted,
            include_sdc=False,
        )
    )

    clean = (
        build_clean_observation_scene(
            ideal_scene=ideal,
            config=clean_config,
        )
    )

    degraded = (
        build_degraded_observation_scene(
            clean_scene=clean,
            config=degraded_config,
        )
    )

    algorithm_hash = (
        degraded_algorithm_sha256(
            degraded
        )
    )

    sequence = (
        algorithm_sequence_from_degraded_scene(
            scenario_id=(
                scenario.scenario_id
            ),
            scene=degraded,
        )
    )

    associated = (
        associate_estimated_gnn(
            sequence
        )
    )

    dynamic_frames, _ = (
        build_causal_dynamic_headlamp_frames(
            adapted
        )
    )

    expected = (
        int(
            scenario.current_time_index
        )
        +
        1
    )

    if (
        len(dynamic_frames)
        !=
        expected
        or
        any(
            frame is None
            for frame
            in dynamic_frames
        )
    ):
        raise RuntimeError(
            "Invalid causal dynamic "
            "headlamp frames."
        )

    timestamps = tuple(
        float(x)
        for x in (
            scenario
            .timestamps_seconds[
                :expected
            ]
        )
    )

    context = (
        FrameTransformContext(
            T_H0_from_W=(
                adapted.frames
                .T_H0_from_W
            ),
            T_Ht_from_W_by_frame=tuple(
                frame.T_Ht_from_W
                for frame
                in dynamic_frames
            ),
        )
    )

    scene_inputs = (
        build_causal_scene_inputs(
            associated.tracks,
            scenario_id=(
                scenario.scenario_id
            ),
            context=context,
            timestamps_s=(
                timestamps
            ),
        )
    )

    return {
        "adapted":
            adapted,

        "degraded":
            degraded,

        "stage2_algorithm_sha256":
            algorithm_hash,

        "association_track_count":
            len(
                associated.tracks
            ),

        "scene_inputs":
            scene_inputs,
    }

