def _map_message_points(
    message,
):
    for name in (
        "polyline",
        "polygon",
    ):
        if hasattr(
            message,
            name,
        ):
            values = getattr(
                message,
                name,
            )

            for point in values:
                if all(
                    hasattr(
                        point,
                        axis,
                    )
                    for axis in (
                        "x",
                        "y",
                        "z",
                    )
                ):
                    yield (
                        float(point.x),
                        float(point.y),
                        float(point.z),
                    )

    if hasattr(
        message,
        "position",
    ):
        point = getattr(
            message,
            "position",
        )

        if all(
            hasattr(
                point,
                axis,
            )
            for axis in (
                "x",
                "y",
                "z",
            )
        ):
            yield (
                float(point.x),
                float(point.y),
                float(point.z),
            )

def build_static_map_index_H0(
    scenario,
    *,
    T_H0_from_W,
):
    result = {
        category: []
        for category in (
            MAP_CATEGORIES
        )
    }

    for feature in (
        scenario.map_features
    ):
        try:
            kind = (
                feature.WhichOneof(
                    "feature_data"
                )
            )
        except Exception:
            kind = None

        if kind not in result:
            continue

        message = getattr(
            feature,
            kind,
        )

        for point_W in (
            _map_message_points(
                message
            )
        ):
            point_H0 = (
                T_H0_from_W
                .apply_point(
                    point_W
                )
            )

            result[kind].append(
                tuple(
                    float(x)
                    for x in point_H0
                )
            )

    return {
        key:
            tuple(value)
        for key, value
        in result.items()
    }

def map_context_summary(
    map_index_H0,
    *,
    target_position_H0_m: Vec3,
) -> tuple[float, ...]:
    tx, ty, _ = (
        target_position_H0_m
    )

    output = []

    for category in (
        MAP_CATEGORIES
    ):
        points = (
            map_index_H0
            .get(
                category,
                (),
            )
        )

        distances = [
            hypot(
                point[0] - tx,
                point[1] - ty,
            )
            for point in points
        ]

        if distances:
            nearest = min(
                distances
            )

            count = sum(
                distance
                <=
                MAP_RADIUS_M
                for distance
                in distances
            )

        else:
            nearest = (
                MAP_EMPTY_DISTANCE_M
            )

            count = 0

        output.extend(
            (
                float(nearest),
                float(count),
            )
        )

    result = tuple(
        output
    )

    if len(result) != (
        MAP_CONTEXT_DIM
    ):
        raise RuntimeError(
            "Map-context dimension changed."
        )

    return result

def map_component_index(
    mixture_logits: torch.Tensor,
) -> torch.Tensor:
    return torch.argmax(
        mixture_logits,
        dim=-1,
    )

def map_component_mean(
    mixture_logits: torch.Tensor,
    means: torch.Tensor,
) -> torch.Tensor:
    if means.ndim != 4:
        raise ValueError(
            "means must be [B,K,H,3]."
        )

    index = map_component_index(
        mixture_logits
    )

    batch = torch.arange(
        means.shape[0],
        device=means.device,
    )

    return means[
        batch,
        index,
        :,
        :
    ]

def normalize_map_context(
    value: torch.Tensor,
    stats: NormalizationStats,
) -> torch.Tensor:
    mean = torch.tensor(
        stats.map_mean,
        dtype=value.dtype,
        device=value.device,
    )

    std = torch.tensor(
        stats.map_std,
        dtype=value.dtype,
        device=value.device,
    )

    return (
        value
        -
        mean
    ) / std
